using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Abastecimiento.DTOs;using TransPort.Api.Modules.Abastecimiento.Repositories;
namespace TransPort.Api.Tests;
public sealed class AbastecimientosControllerTests
{
 [Fact]public async Task Listar_PropagaAlcanceEmpleado(){var r=new Fake();var c=C(r,12,"Empleado");await c.Listar(null,null,default);Assert.Equal(new AlcanceAbastecimiento(12,false),r.Alcance);}
 [Fact]public async Task Crear_DevuelveIdentificador(){var r=new Fake{Id=44};var c=C(r,1,"AdministradorGeneral");var x=Assert.IsType<OkObjectResult>(await c.Crear(new(){GiroSolicitanteId=1,SedeSolicitanteId=1,GiroProveedorId=2,SedeProveedorId=2,FechaNecesaria=DateTime.Today.AddDays(1),Motivo="Solicitud válida",Detalles=[new(){ArticuloProveedorId=1,ArticuloDestinoId=2,Cantidad=1}]},default));Assert.Equal(44,Assert.IsType<ResultadoAbastecimientoDto>(x.Value).Id);}
 [Fact]public async Task Obtener_Inexistente_DevuelveNotFound(){Assert.IsType<NotFoundResult>(await C(new Fake(),1,"AdministradorGeneral").Obtener(99,default));}
 [Fact]public void Controlador_ExcluyeCliente(){var a=typeof(AbastecimientosController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");Assert.Contains("Empleado",a.Roles??"");}
 private static AbastecimientosController C(IAbastecimientoRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}
 private sealed class Fake:IAbastecimientoRepository{public long Id{get;init;}public AlcanceAbastecimiento?Alcance{get;private set;}public Task<IReadOnlyList<AbastecimientoListadoDto>>ListarAsync(string?e,string?b,AlcanceAbastecimiento a,CancellationToken ct){Alcance=a;return Task.FromResult<IReadOnlyList<AbastecimientoListadoDto>>([]);}public Task<AbastecimientoDetalleDto?>ObtenerAsync(long id,AlcanceAbastecimiento a,CancellationToken ct)=>Task.FromResult<AbastecimientoDetalleDto?>(null);public Task<AbastecimientoOpcionesDto>OpcionesAsync(AlcanceAbastecimiento a,CancellationToken ct)=>Task.FromResult(new AbastecimientoOpcionesDto([],[],[],[],[]));public Task<long>CrearAsync(CrearAbastecimientoRequest x,AlcanceAbastecimiento a,CancellationToken ct){Alcance=a;return Task.FromResult(Id);}public Task<bool>CambiarEstadoAsync(long id,CambiarEstadoAbastecimientoRequest x,AlcanceAbastecimiento a,CancellationToken ct)=>Task.FromResult(true);public Task ComentarAsync(long id,string c,AlcanceAbastecimiento a,CancellationToken ct)=>Task.CompletedTask;public Task<bool>EliminarAsync(long id,int u,CancellationToken ct)=>Task.FromResult(true);}
}
